python3 - <<'PY'
import json, collections
p='.claudinite-checks.json'
d=json.load(open(p), object_pairs_hook=collections.OrderedDict)
for e in d['packs']:
    if not isinstance(e, dict): continue
    if e['id']=='barriers':
        e['config']={"rules":[
          {"between":["src/backend","src/frontend"],
           "allow":["src/shared"],
           "reason":"the Workers back end and the Pages front end deploy as two independent artifacts and integrate over the HTTP API only — they share the contract in src/shared and nothing else"}
        ]}
    if e['id']=='claude-code-web-users-support':
        e['config']={"repo":"missingbulb/Shepherd"}
open(p,'w').write(json.dumps(d,indent=2,ensure_ascii=False)+"\n")
PY
node .claudinite/shared/engine/checks/check_the_world.mjs 2>&1 | tail -40
